#include <iostream>
#include <string>
#include <iomanip>

// Base class demonstrating access levels and constructors
class Account {
private:
    double balance_{0.0};

public:
    Account() = default;
    explicit Account(double balance) : balance_(balance >= 0.0 ? balance : 0.0) {
        if (balance < 0.0) {
            std::cout << "Initial balance invalid. Reset to 0.0.\n";
        }
    }

    virtual ~Account() = default;

    void credit(double amount) {
        if (amount > 0.0) {
            balance_ += amount;
        }
    }

    bool debit(double amount) {
        if (amount <= balance_) {
            balance_ -= amount;
            return true;
        }
        std::cout << "Debit amount exceeded account balance.\n";
        return false;
    }

    double getBalance() const noexcept {
        return balance_;
    }
};

// Derived class using C++11 inherited constructors
class SimpleSavingsAccount : public Account {
private:
    double interestRate_{0.05}; // Default in-class member initialization

public:
    // Inherit Account() and Account(double)
    using Account::Account;

    // Additional custom constructor
    SimpleSavingsAccount(double balance, double rate)
        : Account(balance), interestRate_(rate >= 0.0 ? rate : 0.0) {}

    double calculateInterest() const noexcept {
        return getBalance() * interestRate_;
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    // Using inherited constructor Account(double)
    SimpleSavingsAccount acc1(1000.0);
    std::cout << "acc1 balance: " << acc1.getBalance() << "\n";
    std::cout << "acc1 interest: " << acc1.calculateInterest() << "\n";

    // Using custom constructor
    SimpleSavingsAccount acc2(500.0, 0.08);
    acc2.credit(acc2.calculateInterest());
    std::cout << "acc2 new balance after credit: " << acc2.getBalance() << "\n";

    // Attempt debit exceeding balance
    acc2.debit(1000.0);

    return 0;
}

