#include <iostream>
#include <string>
#include <iomanip>

class Package {
private:
    std::string senderName_;
    std::string recipientName_;
    double weight_{0.0};       // in ounces
    double costPerOunce_{0.0}; // cost per ounce

public:
    Package(std::string sender, std::string recipient, double weight, double costPerOunce)
        : senderName_(std::move(sender)), recipientName_(std::move(recipient)),
          weight_(weight > 0.0 ? weight : 0.0),
          costPerOunce_(costPerOunce > 0.0 ? costPerOunce : 0.0) {}

    double calculateCost() const noexcept {
        return weight_ * costPerOunce_;
    }

    double getWeight() const noexcept { return weight_; }
    double getCostPerOunce() const noexcept { return costPerOunce_; }
};

class TwoDayPackage : public Package {
private:
    double flatFee_{0.0};

public:
    TwoDayPackage(std::string sender, std::string recipient, double weight, double costPerOunce, double flatFee)
        : Package(std::move(sender), std::move(recipient), weight, costPerOunce),
          flatFee_(flatFee >= 0.0 ? flatFee : 0.0) {}

    double calculateCost() const noexcept {
        return Package::calculateCost() + flatFee_;
    }
};

class OvernightPackage : public Package {
private:
    double additionalFeePerOunce_{0.0};

public:
    OvernightPackage(std::string sender, std::string recipient, double weight, double costPerOunce, double extraFee)
        : Package(std::move(sender), std::move(recipient), weight, costPerOunce),
          additionalFeePerOunce_(extraFee >= 0.0 ? extraFee : 0.0) {}

    double calculateCost() const noexcept {
        return getWeight() * (getCostPerOunce() + additionalFeePerOunce_);
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    Package pkg("Alice", "Bob", 10.0, 0.50);
    TwoDayPackage twoDay("Charlie", "Dave", 10.0, 0.50, 5.00);
    OvernightPackage overnight("Eve", "Frank", 10.0, 0.50, 0.25);

    std::cout << "Standard package cost: $" << pkg.calculateCost() << "\n";
    std::cout << "Two-day package cost: $" << twoDay.calculateCost() << "\n";
    std::cout << "Overnight package cost: $" << overnight.calculateCost() << "\n";

    return 0;
}
